head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();
        $c.cm.PanelToGroupBox(panel_1);
        await scwin.setCode();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26301.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26301.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name btn_GridToExcel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_GridToExcel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF26301.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "요약재무정보", type: "2"}); // 엑셀 다운로드
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.btn_GridToExcel_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (window.event.keyCode === 40) {
            // 아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            if (window.event.keyCode === 13) {
                $c.cm.fn_com_Confirm_set();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name cmb_ACNT_TP_CD_onselchange
 * @description cmb_ACNT_TP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ACNT_TP_CD_onselchange = function() {
    try {
        let str = cmb_ACNT_TP_CD.getValue();
        if (str === "1" || str === "2") {
            grd_Grid.show("");
            grd_Grid2.hide();
            dts_Grid2.removeAll();
        } else if (str === "3" || str === "4") {
            grd_Grid.hide();
            dts_Grid.removeAll();
            grd_Grid2.show("");
            grd_Grid2.style.left = grd_Grid.style.left;
            grd_Grid2.style.top = grd_Grid.style.top;
            grd_Grid2.setGridWidth(grd_Grid.getStyle("width"));
            grd_Grid2.setGridHeight(grd_Grid.getStyle("height"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.cmb_ACNT_TP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        let FISCAL_YYYY1 = dts_Grid.getCellData(1, "FISCAL_YYYY1");
        let FISCAL_YYYY2 = dts_Grid.getCellData(1, "FISCAL_YYYY2");
        let FISCAL_YYYY3 = dts_Grid.getCellData(1, "FISCAL_YYYY3");
        $c.cm.setColumnProp(grd_Grid, "FISCAL_YYYY1", "Name", FISCAL_YYYY1);
        $c.cm.setColumnProp(grd_Grid, "FISCAL_YYYY2", "Name", FISCAL_YYYY2);
        $c.cm.setColumnProp(grd_Grid, "FISCAL_YYYY3", "Name", FISCAL_YYYY3);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26301.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Grid2_OnLoadCompleted
 * @description dts_Grid2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid2_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        let FISCAL_YYYY1 = dts_Grid2.getCellData(1, "FISCAL_YYYY1");
        let FISCAL_YYYY2 = dts_Grid2.getCellData(1, "FISCAL_YYYY2");
        let FISCAL_YYYY3 = dts_Grid2.getCellData(1, "FISCAL_YYYY3");
        $c.cm.setColumnProp(grd_Grid2, "FISCAL_YYYY1", "Name", FISCAL_YYYY1);
        $c.cm.setColumnProp(grd_Grid2, "FISCAL_YYYY2", "Name", FISCAL_YYYY2);
        $c.cm.setColumnProp(grd_Grid2, "FISCAL_YYYY3", "Name", FISCAL_YYYY3);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.dts_Grid2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid2_OnLoadError
 * @description dts_Grid2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid2_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF26301.dts_Grid2_OnLoadError" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF26301.txb_ISUR_CD_onkeyup" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 결산기구분코드.(통합DB)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    // 결산기구분코드.(통합DB)
    const sbmOptions = {
        id : "sbm_dts_FISCYY_TP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_FISCYY_TP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_FISCYY.DataID = "";
    dts_FISCYY.Reset();
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    let str = "";
    for (let i = yyyy; i >= 1998; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    // alert(str);
    cmb_FISCYY.CBData = str;
    rdo_MKT_ID.setValue(js_market);
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const MKT_ID = rdo_MKT_ID.getValue();
    const FISCYY = cmb_FISCYY.getValue();
    const ISUR_CD = txb_ISUR_CD.getValue();
    // var FISCYY_TP_CD = getObjectValue(cmb_FISCYY_TP_CD);
    // var CURR_UNIT_CD = getObjectValue(cmb_CURR_UNIT_CD);
    const ACNT_TP_CD = cmb_ACNT_TP_CD.getValue();
    if (ISUR_CD === "") {
        await $c.win.alert("[회사]를 입력하세요.");
        txb_ISUR_CD.focus();
        return;
    }
    url += "&MKT_ID=" + MKT_ID;
    url += "&ISUR_CD=" + ISUR_CD;
    url += "&FISCYY=" + FISCYY;
    // url += "&FISCYY_TP_CD=" + FISCYY_TP_CD; // 분기
    // url += "&CURR_UNIT_CD=" + CURR_UNIT_CD; // 단위
    url += "&ACNT_TP_CD=" + ACNT_TP_CD; // 1:대차, 2:손익,3:이익잉여,4:현금흐름표
    url += "&SCREN_ID=" + 'ULDSTF26301.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    if (ACNT_TP_CD === "1" || ACNT_TP_CD === "2") {
        const sbmOptions = {
            id : "sbm_dts_Grid",
            action : "/DisclosureCountStatistics.do",
            ref : "",
            target : "dts_Grid=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else if (ACNT_TP_CD === "3" || ACNT_TP_CD === "4") {
        const sbmOptions = {
            id : "sbm_dts_Grid2",
            action : "/DisclosureCountStatistics.do",
            ref : "",
            target : "dts_Grid2=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    // showObj(panel_debug, false);
    grd_Grid2.hide();
    panel_mkt.hide();
};
